app.use(morgan('combined'));

// 404
app.use((req, res) => res.status(404).json({ error: 'Not found' }));

// Central error handler — last middleware
app.use((err, req, res, _next) => {
  // Log full details server-side, return generic message to client
  console.error({ err: err.stack, path: req.path });
  res.status(err.status || 500).json({ error: 'Internal server error' });
});
```

Be careful never to log secrets, tokens, or full request bodies for auth endpoints.

