app.use(express.json({ limit: '10kb' })); // prevent JSON bomb DoS

const CreateUser = z.object({
  name: z.string().min(1).max(100),
  email: z.string().email().max(254),
});

app.post('/users', requireAuth, (req, res) => {
  const parsed = CreateUser.safeParse(req.body);
  if (!parsed.success) {
    return res.status(400).json({ error: parsed.error.flatten() });
  }
  // ...use parsed.data, never req.body, downstream
});
```

If you later add SQL, **always use parameterized queries** (`db.query('SELECT * FROM users WHERE id = $1', [id])`) — never string concatenation.

---

### 6. ⚠️ Hardcoded Port, No Config Hygiene (OWASP A05)
**Severity:** Low

```js
